------------ lifeCycle ------------


function UIBattlingTotalDamage:CleanProperties()
    self.isShow = false
    self.coShowTotalDamage = nil
    self.RT_FXRoot = nil
    self.CanvasGroup_FXRoot = nil
end

function UIBattlingTotalDamage:SetDamage(value)
    -- print("[总伤害] SetDamage", self, debug.traceback())
    self.Txt_Bottom.text = tostring(value)
    self.Txt_Top.text = tostring(value)

    if self.coShowTotalDamage then
        cs_coroutine.stop(self.coShowTotalDamage)
        self.coShowTotalDamage = nil
    end

    -- 如果入场动画没播完，那么等待播完
    if self.Animation_Root:IsPlaying(ANIMA_PATH_TOTAL_DAMAGE_PLAY) then
        return
    end

    -- 可能打断出现的动画，导致位置和透明度都不对，这里直接强设一下
    local pos = self.RT_FXRoot.localPosition
    self.RT_FXRoot.localPosition = Vector3.New(pos.x, 0, pos.z)
    self.CanvasGroup_FXRoot.alpha = 1

    -- 重播repeat动画
    self.Animation_Root:Stop()
    self.Animation_Root:Play(ANIMA_PATH_TOTAL_DAMAGE_REPEAT)
end

function UIBattlingTotalDamage:ShowPanel()
    -- print("[总伤害] ShowPanel", self, debug.traceback())
    self.isShow = true
    KTool.SetActive(self.RT_Root, true)
    
    -- hide动画会改坐标，这里需要复原一下
    local pos = self.RT_FXRoot.localPosition
    self.RT_FXRoot.localPosition = Vector3.New(pos.x, 0, pos.z)
end

function UIBattlingTotalDamage:HidePanel()
    -- print("[总伤害] HidePanel", self, debug.traceback())
    if self.RT_Root.gameObject.activeSelf and IsNull(self.coShowTotalDamage) then
        self.coShowTotalDamage = cs_coroutine.start(function()
            -- 延迟0.5s播放退出动画
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))

            --- 消失动画
            self.Animation_Root:Play(ANIMA_PATH_TOTAL_DAMAGE_OUT)
            local animState = self.Animation_Root:get_Item(ANIMA_PATH_TOTAL_DAMAGE_OUT)
            if isNotNull(animState) then
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(animState.length))
            end
            KTool.SetActive(self.RT_Root, false)
            self.isShow = false
            self.coShowTotalDamage = nil
        end)
    end
end

